"""Targeted write-audited tests; every generated byte remains in a fresh runtime root."""
import argparse,hashlib,json,os,sys,time,unittest
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];sys.dont_write_bytecode=True;sys.path[:0]=[str(ROOT),str(ROOT/'tools'),str(ROOT/'studio_ui_tests')]
from run_visual_resume_tests import guard,hashes

def main():
 p=argparse.ArgumentParser();p.add_argument('--run-id',required=True);a=p.parse_args()
 if not a.run_id.startswith('visual-') or any(c not in 'abcdefghijklmnopqrstuvwxyz0123456789-' for c in a.run_id):raise SystemExit('Fresh visual- run ID required.')
 root=ROOT/'.runtime/studio-ui'/a.run_id
 for parent in (root,*root.parents):
  if parent.is_symlink():raise SystemExit('Symlink refused')
 root.mkdir(exist_ok=False,mode=0o700);os.environ['LOCAL_TEST_ROOT']=str(root)
 before=hashes();rejected,commands=guard(root,child=True)
 from test_local_tools import LocalToolsTests
 started=time.monotonic()
 with (root/'tests.txt').open('x') as f:r=unittest.TextTestRunner(stream=f,verbosity=2).run(unittest.defaultTestLoader.loadTestsFromTestCase(LocalToolsTests))
 after=hashes();drift=[n for n in set(before)|set(after) if before.get(n)!=after.get(n)]
 report={'tests':r.testsRun,'failures':len(r.failures),'errors':len(r.errors),'seconds':time.monotonic()-started,'unexpected_source_changes':drift,'rejected':rejected,'commands':commands,'source_hashes':{n:h for n,h in after.items() if n.startswith(('tools/studio_local','tools/run_local_tools','studio_ui_tests/test_local','Start Studio','docs/LOCAL_STUDIO'))},'external_network':False,'real_media':False}
 (root/'results.json').write_text(json.dumps(report,indent=2));print(json.dumps(report));return 0 if r.wasSuccessful() and not drift and not commands else 1
if __name__=='__main__':raise SystemExit(main())
